#### P1126 \[CERC1996\] 机器人搬重物（已解决）
https://www.luogu.com.cn/problem/P1126
如果没有 1.6 米的身材问题，这是一道可以使用非常经典的 dfs 解法通过的题，bfs 参考 [[#BFS#P1126 [CERC1996 ] 机器人搬重物|BFS > P1126 [CERC1996 ] 机器人搬重物]]
```cpp
int			n, m, x, y, x_target, y_target, min_cost = INT_MAX;
vector<int> direction = {
	2,	 // E (+col):  偶 → y += 1            = 向右
	-1,	 // N (-row): 奇 → x -= 1            = 向上
	-2,	 // W (-col): 偶 → y -= 1            = 向左
	1	 // S (+row): 奇 → x += 1            = 向下
};

bool is_outside(int x, int y) {
	if(0 <= x && x < n && 0 <= y && y < m) {
		return false;
	}
	return true;
}

bool is_block(int x, int y, vector<vector<int>>& matrix) {
	if(matrix[x][y] == 1) {
		return true;
	}
	return false;
}

void dfs(int						  x,
		 int						  y,
		 vector<vector<int>>&		  matrix,
		 vector<vector<vector<int>>>& records,
		 int						  face_to_index,
		 int						  step,
		 int						  cost) {
	for(int s = 0; s < step; s++) {
		if(direction[face_to_index] % 2 == 0) {
			y += direction[face_to_index] / 2;
		} else {
			x += direction[face_to_index];
		}
		if(is_outside(x, y) || is_block(x, y, matrix)) {
			return;
		}
	}
	cost++;
	if(records[x][y][direction[face_to_index] + 2] <= cost) {
		return;
	}
	records[x][y][direction[face_to_index] + 2] = cost;
	if(x == x_target && y == y_target) {
		min_cost = min(min_cost, cost);
	}
	int face_turn_left	= ((face_to_index + 1) % 4 + 4) % 4;
	int face_turn_right = ((face_to_index - 1) % 4 + 4) % 4;
	dfs(x, y, matrix, records, face_turn_right, 0, cost);
	dfs(x, y, matrix, records, face_turn_left, 0, cost);
	dfs(x, y, matrix, records, face_to_index, 1, cost);
	dfs(x, y, matrix, records, face_to_index, 2, cost);
	dfs(x, y, matrix, records, face_to_index, 3, cost);
}

int main() {
	cin >> n >> m;
	char						face;
	vector<vector<vector<int>>> records(n, vector<vector<int>>(m, vector<int>(6, INT_MAX)));
	vector<vector<int>>			matrix(n, vector<int>(m, 0));
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < m; j++) {
			cin >> matrix[i][j];
		}
	}
	cin >> x >> y >> x_target >> y_target >> face;
	int face_to_index;
	switch(face) {
	case 'S':
		face_to_index = 3;
		break;
	case 'W':
		face_to_index = 2;
		break;
	case 'E':
		face_to_index = 0;
		break;
	default:
		face_to_index = 1;
		break;
	}
	int face_turn_left	= ((face_to_index + 1) % 4 + 4) % 4;
	int face_turn_right = ((face_to_index - 1) % 4 + 4) % 4;
	dfs(x, y, matrix, records, face_turn_right, 0, 0);
	dfs(x, y, matrix, records, face_turn_left, 0, 0);
	dfs(x, y, matrix, records, face_to_index, 1, 0);
	dfs(x, y, matrix, records, face_to_index, 2, 0);
	dfs(x, y, matrix, records, face_to_index, 3, 0);
	cout << (min_cost == INT_MAX ? -1 : min_cost);
}
```
注意，容易丢掉直行超过 1 米时**可能会穿过障碍**的问题

